import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry matvec_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M_param,
    .param .u32 K_param
)
{
    .reg .pred %p;
    .reg .b32 %r_tid, %r_ntid, %r_bid, %r_M, %r_K, %r_lane, %r_warp, %r_nwarps, %r_tmp, %r_mask;
    .reg .f32 %f_sum, %f_a, %f_b, %f_tmp;
    .reg .b64 %rd_A, %rd_B, %rd_C, %rd_a_elem, %rd_b_elem, %rd_tmp, %rd_baseA_elems, %rd_idx_elems, %rd_byte_off, %rd_sbase;

    .shared .align 4 .b8 s_sums[128]; // up to 32 warps (1024 threads)

    // Load parameters
    ld.param.u64 %rd_A, [A_ptr];
    ld.param.u64 %rd_B, [B_ptr];
    ld.param.u64 %rd_C, [C_ptr];
    ld.param.u32 %r_M, [M_param];
    ld.param.u32 %r_K, [K_param];

    // Thread/block indices
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_ntid, %ntid.x;
    mov.u32 %r_bid, %ctaid.x;

    // Bounds check: row index < M
    setp.ge.u32 %p, %r_bid, %r_M;
    @%p bra DONE;

    // Compute base element index for row in A: base = (u64)row * (u64)K
    cvt.u64.u32 %rd_tmp, %r_bid;
    cvt.u64.u32 %rd_idx_elems, %r_K;
    mul.lo.u64 %rd_baseA_elems, %rd_tmp, %rd_idx_elems;

    // Initialize sum
    mov.f32 %f_sum, 0f00000000;

    // Loop over K with stride blockDim.x
    cvt.u64.u32 %rd_idx_elems, %r_tid; // i = tid
LOOP:
    // if (i >= K) break
    cvt.u32.u64 %r_tmp, %rd_idx_elems;
    setp.ge.u32 %p, %r_tmp, %r_K;
    @%p bra REDUCE;

    // Load A[row, i]
    add.u64 %rd_tmp, %rd_baseA_elems, %rd_idx_elems;   // idxA = base + i
    mul.lo.u64 %rd_byte_off, %rd_tmp, 4;               // byte offset
    add.u64 %rd_a_elem, %rd_A, %rd_byte_off;
    ld.global.f32 %f_a, [%rd_a_elem];

    // Load B[i]
    mul.lo.u64 %rd_byte_off, %rd_idx_elems, 4;
    add.u64 %rd_b_elem, %rd_B, %rd_byte_off;
    ld.global.f32 %f_b, [%rd_b_elem];

    // Accumulate
    fma.rn.f32 %f_sum, %f_a, %f_b, %f_sum;

    // i += blockDim.x
    cvt.u64.u32 %rd_tmp, %r_ntid;
    add.u64 %rd_idx_elems, %rd_idx_elems, %rd_tmp;
    bra LOOP;

REDUCE:
    // Warp-level reduction
    and.b32 %r_lane, %r_tid, 31;
    shr.u32 %r_warp, %r_tid, 5;
    mov.u32 %r_mask, 0xffffffff;

    shfl.sync.down.b32 %f_tmp, %f_sum, 16, 32, %r_mask;
    add.f32 %f_sum, %f_sum, %f_tmp;
    shfl.sync.down.b32 %f_tmp, %f_sum, 8, 32, %r_mask;
    add.f32 %f_sum, %f_sum, %f_tmp;
    shfl.sync.down.b32 %f_tmp, %f_sum, 4, 32, %r_mask;
    add.f32 %f_sum, %f_sum, %f_tmp;
    shfl.sync.down.b32 %f_tmp, %f_sum, 2, 32, %r_mask;
    add.f32 %f_sum, %f_sum, %f_tmp;
    shfl.sync.down.b32 %f_tmp, %f_sum, 1, 32, %r_mask;
    add.f32 %f_sum, %f_sum, %f_tmp;

    // Store per-warp reduction to shared memory from lane 0
    mov.u64 %rd_sbase, s_sums;
    setp.ne.u32 %p, %r_lane, 0;
    @%p bra SKIP_STORE;
    cvt.u64.u32 %rd_tmp, %r_warp;
    mul.lo.u64 %rd_tmp, %rd_tmp, 4;
    add.u64 %rd_tmp, %rd_sbase, %rd_tmp;
    st.shared.f32 [%rd_tmp], %f_sum;
SKIP_STORE:
    bar.sync 0;

    // Number of warps in the block
    add.u32 %r_nwarps, %r_ntid, 31;
    shr.u32 %r_nwarps, %r_nwarps, 5;

    // Final reduction in first warp
    setp.ne.u32 %p, %r_warp, 0;
    @%p bra POST_REDUCE;

    setp.ge.u32 %p, %r_tid, %r_nwarps;
    @%p bra LOAD_ZERO;
    cvt.u64.u32 %rd_tmp, %r_tid;
    mul.lo.u64 %rd_tmp, %rd_tmp, 4;
    add.u64 %rd_tmp, %rd_sbase, %rd_tmp;
    ld.shared.f32 %f_sum, [%rd_tmp];
    bra AFTER_LOAD;
LOAD_ZERO:
    mov.f32 %f_sum, 0f00000000;
AFTER_LOAD:

    shfl.sync.down.b32 %f_tmp, %f_sum, 16, 32, %r_mask;
    add.f32 %f_sum, %f_sum, %f_tmp;
    shfl.sync.down.b32 %f_tmp, %f_sum, 8, 32, %r_mask;
    add.f32 %f_sum, %f_sum, %f_tmp;
    shfl.sync.down.b32 %f_tmp, %f_sum, 4, 32, %r_mask;
    add.f32 %f_sum, %f_sum, %f_tmp;
    shfl.sync.down.b32 %f_tmp, %f_sum, 2, 32, %r_mask;
    add.f32 %f_sum, %f_sum, %f_tmp;
    shfl.sync.down.b32 %f_tmp, %f_sum, 1, 32, %r_mask;
    add.f32 %f_sum, %f_sum, %f_tmp;

    // Write result from lane 0
    setp.ne.u32 %p, %r_lane, 0;
    @%p bra POST_REDUCE;

    cvt.u64.u32 %rd_tmp, %r_bid;
    mul.lo.u64 %rd_byte_off, %rd_tmp, 4;
    add.u64 %rd_tmp, %rd_C, %rd_byte_off;
    st.global.f32 [%rd_tmp], %f_sum;

POST_REDUCE:
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matvec_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M = int(A.shape[0])
        K = int(A.shape[1])
        C = torch.empty((M, 1), device=A.device, dtype=A.dtype)
        module = _get_ptx_module()
        block_x = 256
        grid_x = M
        module.launch(
            "matvec_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[A, B, C, i32(M), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

