_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matvec_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M = int(A.shape[0])
        K = int(A.shape[1])
        C = torch.empty((M, 1), device=A.device, dtype=A.dtype)
        module = _get_ptx_module()
        block_x = 256
        grid_x = M
        module.launch(
            "matvec_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[A, B, C, i32(M), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C
